package main

const groupManagementHTML = `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>分组管理</title>
<style>
:root{color-scheme:light dark;font-family:Inter,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;padding:20px;background:#f5f7fb;color:#18212f}.shell{max-width:1320px;margin:auto}.toolbar,.panel{background:#fff;border:1px solid #dfe5ee;border-radius:14px;box-shadow:0 4px 18px rgba(28,39,60,.06)}.toolbar{display:flex;gap:10px;align-items:center;padding:14px;margin-bottom:16px;position:sticky;top:0;z-index:3}.toolbar input{flex:1}.panel{padding:18px;margin-bottom:16px}h1{font-size:22px;margin:0 12px 0 0}h2{font-size:18px;margin:0 0 14px}.muted{color:#6b7280;font-size:13px}.status{margin-left:auto;font-size:13px}.ok{color:#087f5b}.error{color:#c92a2a}button,input,select{border:1px solid #cfd7e3;border-radius:8px;padding:9px 11px;background:#fff;color:inherit}button{cursor:pointer;background:#edf2ff;border-color:#bac8ff}button.primary{background:#3451db;color:#fff;border-color:#3451db}button.danger{background:#fff0f0;border-color:#ffc9c9;color:#c92a2a}button:disabled{opacity:.5;cursor:not-allowed}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.card{border:1px solid #dfe5ee;border-radius:12px;padding:14px;background:#fbfcfe}.row{display:grid;grid-template-columns:140px 1fr;gap:10px;align-items:center;margin:8px 0}.row label{font-size:13px;color:#495264}.row input{width:100%}.card-head{display:flex;align-items:center;gap:8px;margin-bottom:10px}.card-head strong{flex:1}.badge{font-size:12px;padding:3px 7px;border-radius:999px;background:#e7f5ff;color:#1971c2}.auth-table{width:100%;border-collapse:collapse}.auth-table th,.auth-table td{text-align:left;padding:10px;border-bottom:1px solid #edf0f4;vertical-align:middle}.auth-table th{font-size:12px;color:#6b7280}.auth-table input{width:100%;min-width:180px}.empty{padding:24px;text-align:center;color:#6b7280}.actions{display:flex;gap:8px;flex-wrap:wrap}.secret{font-family:ui-monospace,monospace}@media(max-width:900px){.grid{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}.toolbar h1{width:100%}.auth-table{display:block;overflow:auto}}
@media(prefers-color-scheme:dark){body{background:#111827;color:#e5e7eb}.toolbar,.panel,.card{background:#18212f;border-color:#334155}.card{background:#151e2b}button,input,select{background:#111827;border-color:#475569}.muted,.row label,.auth-table th{color:#9ca3af}.auth-table th,.auth-table td{border-color:#334155}}
</style>
</head>
<body><div class="shell">
<div class="toolbar"><h1>分组管理</h1><input id="managementKey" type="password" placeholder="CPA 管理密钥，仅保存在当前标签页"><button id="connect" class="primary">连接</button><button id="refresh">刷新账号</button><button id="save" class="primary">保存</button><span id="status" class="status muted">未连接</span></div>
<section class="panel"><h2>下游 API Key 策略</h2><p class="muted">插件是独占认证提供者。分组留空或填写 * 表示可以使用全部账号。</p><div id="keys" class="grid"></div><div style="margin-top:12px"><button id="addKey">新增密钥</button></div></section>
<section class="panel"><h2>账号分组</h2><p class="muted">账号分组按稳定 auth_index 保存到插件配置；首次加载会兼容读取旧账号 JSON 中的 groups。</p><div id="auths"></div></section>
<section class="panel"><h2>运行设置</h2><div class="row"><label for="refreshSeconds">账号缓存刷新秒数</label><input id="refreshSeconds" type="number" min="5" max="3600" value="60"></div><p id="runtime" class="muted"></p></section>
</div>
<script>
(function(){
var config=null,state=null;
var keyInput=document.getElementById('managementKey');
var saved=sessionStorage.getItem('lzz-groups-management-key')||'';if(saved)keyInput.value=saved;
function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]});}
function setStatus(message,error){var el=document.getElementById('status');el.textContent=message;el.className='status '+(error?'error':'ok');}
function managementKey(){return keyInput.value.trim();}
async function api(path,options){options=options||{};var headers=Object.assign({'Content-Type':'application/json','Authorization':'Bearer '+managementKey()},options.headers||{});var response=await fetch(path,Object.assign({},options,{headers:headers}));var text=await response.text();var body={};try{body=text?JSON.parse(text):{};}catch(e){throw new Error('HTTP '+response.status+': '+text.slice(0,200));}if(!response.ok)throw new Error(body.message||body.error||('HTTP '+response.status));return body;}
function splitGroups(value){var seen={};return String(value||'').split(',').map(function(v){return v.trim();}).filter(function(v){var k=v.toLowerCase();if(!v||seen[k])return false;seen[k]=true;return true;});}
function randomKey(){var bytes=new Uint8Array(24);crypto.getRandomValues(bytes);return 'sk-'+Array.from(bytes).map(function(v){return v.toString(16).padStart(2,'0');}).join('');}
function renderKeys(){var root=document.getElementById('keys');var policies=Array.isArray(config['api-keys'])?config['api-keys']:[];if(!policies.length){root.innerHTML='<div class="empty">暂无下游密钥</div>';return;}root.innerHTML=policies.map(function(item,index){return '<div class="card key-card" data-index="'+index+'"><div class="card-head"><strong>'+esc(item.label||item.id||('Key '+(index+1)))+'</strong><span class="badge">'+esc(item.id||'自动 ID')+'</span><button class="danger remove-key" type="button">删除</button></div><div class="row"><label>策略 ID</label><input class="policy-id" value="'+esc(item.id||'')+'" placeholder="例如 lzz_plus"></div><div class="row"><label>显示名称</label><input class="policy-label" value="'+esc(item.label||'')+'"></div><div class="row"><label>API Key</label><input class="policy-key secret" type="password" value="'+esc(item.key||'')+'"></div><div class="row"><label>允许分组</label><input class="policy-groups" value="'+esc((item.groups||[]).join(', '))+'" placeholder="lzzplus, grok"></div></div>';}).join('');
Array.from(root.querySelectorAll('.remove-key')).forEach(function(button){button.onclick=function(){var index=Number(button.closest('.key-card').dataset.index);config['api-keys'].splice(index,1);renderKeys();};});}
function renderAuths(){var root=document.getElementById('auths');var auths=state&&Array.isArray(state.auths)?state.auths:[];if(!auths.length){root.innerHTML='<div class="empty">没有读取到账号，请点击刷新账号</div>';return;}root.innerHTML='<table class="auth-table"><thead><tr><th>账号</th><th>来源</th><th>提供商</th><th>优先级</th><th>状态</th><th>模型</th><th>分组</th></tr></thead><tbody>'+auths.map(function(auth){var status=auth.disabled?'disabled':(auth.unavailable?'unavailable':(auth.status||'active'));var account=auth.account?'<div class="muted secret">'+esc(auth.account)+'</div>':'';return '<tr data-auth-index="'+esc(auth.auth_index||auth.id)+'"><td><strong>'+esc(auth.label||auth.name)+'</strong>'+account+'<div class="muted">'+esc(auth.auth_index||auth.id)+'</div></td><td>'+esc(auth.source||'memory')+'</td><td>'+esc(auth.provider)+'</td><td>'+esc(auth.priority||0)+'</td><td>'+esc(status)+'</td><td>'+esc(auth.supported_models_count||0)+'</td><td><input class="auth-groups" value="'+esc((auth.groups||[]).join(', '))+'" placeholder="未分组"><div class="muted">'+esc(auth.group_source||'plugin-config')+'</div></td></tr>';}).join('')+'</tbody></table>';}
function collectKeys(){return Array.from(document.querySelectorAll('.key-card')).map(function(card,index){return {id:card.querySelector('.policy-id').value.trim(),label:card.querySelector('.policy-label').value.trim(),key:card.querySelector('.policy-key').value.trim(),groups:splitGroups(card.querySelector('.policy-groups').value)};}).filter(function(item){return item.key;});}
function collectCredentialGroups(){var result={};Array.from(document.querySelectorAll('tr[data-auth-index]')).forEach(function(row){result[row.dataset.authIndex]=splitGroups(row.querySelector('.auth-groups').value);});return result;}
async function load(force){if(!managementKey())throw new Error('请输入管理密钥');sessionStorage.setItem('lzz-groups-management-key',managementKey());setStatus('加载中...',false);if(force)await api('/v0/management/plugins/lzz-groups/refresh',{method:'POST',body:'{}'});var values=await Promise.all([api('/v0/management/plugins/lzz-groups/config'),api('/v0/management/plugins/lzz-groups/state')]);config=values[0]||{};state=values[1]||{};if(!Array.isArray(config['api-keys']))config['api-keys']=[];if(!config['credential-groups'])config['credential-groups']={};document.getElementById('refreshSeconds').value=config['refresh-seconds']||60;renderKeys();renderAuths();document.getElementById('runtime').textContent='插件 '+(state.version||'')+' · 最近刷新 '+(state.last_refresh||'未知')+(state.last_refresh_error?' · '+state.last_refresh_error:'');setStatus('已连接',false);}
async function save(){if(!config)throw new Error('请先连接');config.enabled=config.enabled!==false;config.priority=Number(config.priority||100);config['api-keys']=collectKeys();config['credential-groups']=collectCredentialGroups();config['refresh-seconds']=Number(document.getElementById('refreshSeconds').value||60);setStatus('保存中...',false);await api('/v0/management/plugins/lzz-groups/config',{method:'PUT',body:JSON.stringify(config)});await new Promise(function(resolve){setTimeout(resolve,600);});await load(true);setStatus('保存成功',false);}
document.getElementById('connect').onclick=function(){load(false).catch(function(error){setStatus(error.message,true);});};
document.getElementById('refresh').onclick=function(){load(true).catch(function(error){setStatus(error.message,true);});};
document.getElementById('save').onclick=function(){save().catch(function(error){setStatus(error.message,true);});};
document.getElementById('addKey').onclick=function(){if(!config){setStatus('请先连接',true);return;}config['api-keys'].push({id:'',label:'',key:randomKey(),groups:[]});renderKeys();};
if(saved)load(false).catch(function(error){setStatus(error.message,true);});
})();
</script></body></html>`
